// C reference for Crucible's editor (hover / completion / signature help).
export default [
  // ───────────── keywords ─────────────
  { name: 'for', kind: 'keyword', sig: 'for (init; cond; step) { ... }', doc: 'Counted loop. Declare the index in *init* (C99+): `for (int i = 0; i < n; i++)`. Any of the three parts may be empty; `for (;;)` loops forever.', example: 'for (int i = 0; i < n; i++)\n    sum += a[i];', insert: 'for (int ${1:i} = 0; ${1:i} < ${2:n}; ${1:i}++) {\n\t$0\n}' },
  { name: 'while', kind: 'keyword', sig: 'while (cond) { ... }', doc: 'Loop while *cond* is non-zero; condition is checked before each iteration.', insert: 'while (${1:cond}) {\n\t$0\n}', example: 'int i = 0;\nwhile (i < n && a[i] != target)\n    i++;' },
  { name: 'do', kind: 'keyword', sig: 'do { ... } while (cond);', doc: 'Loop whose body runs at least once; condition checked after each iteration. Note the trailing semicolon.', insert: 'do {\n\t$0\n} while (${1:cond});', example: 'int x;\ndo {\n    x = rand() % 100;\n} while (x == last);' },
  { name: 'if', kind: 'keyword', sig: 'if (cond) { ... }', doc: 'Conditional. Any non-zero value is true. Gotcha: `if (x = 0)` assigns — use `==`.', insert: 'if (${1:cond}) {\n\t$0\n}', example: 'if (n < 0) {\n    printf("negative\\n");\n}' },
  { name: 'else', kind: 'keyword', sig: 'else { ... }', doc: 'Alternative branch of an `if`; `else if (...)` chains conditions. A dangling `else` binds to the nearest `if`.', insert: 'else {\n\t$0\n}', example: 'if (x % 2 == 0)\n    puts("even");\nelse\n    puts("odd");' },
  { name: 'switch', kind: 'keyword', sig: 'switch (expr) { case K: ... break; default: ... }', doc: 'Multi-way branch on an integer (or char) expression. Cases fall through unless you `break`. Case labels must be integer constants.', insert: 'switch (${1:expr}) {\ncase ${2:0}:\n\t$0\n\tbreak;\ndefault:\n\tbreak;\n}', example: 'switch (op) {\ncase \'+\': r = a + b; break;\ncase \'-\': r = a - b; break;\ndefault: r = 0; break;\n}' },
  { name: 'case', kind: 'keyword', sig: 'case CONST:', doc: 'Label inside a `switch`. Execution falls through to the next case unless you `break`. Declaring a variable right after a label needs braces `{ }`.', insert: 'case ${1:0}:\n\t$0\n\tbreak;', example: 'switch (c) {\ncase \'a\': vowels++; break;\n}' },
  { name: 'default', kind: 'keyword', sig: 'default:', doc: 'Label in a `switch` taken when no `case` matches.', example: 'switch (k) {\ncase 0: puts("zero"); break;\ndefault: puts("other"); break;\n}' },
  { name: 'return', kind: 'keyword', sig: 'return expr;', doc: 'Exit the current function, optionally yielding a value. Never return a pointer to a local (stack) array — `malloc` it instead.', example: 'int square(int x) {\n    return x * x;\n}' },
  { name: 'break', kind: 'keyword', sig: 'break;', doc: 'Exit the innermost loop or `switch`. To leave nested loops, use a flag or `goto`.', example: 'for (int i = 0; i < n; i++) {\n    if (a[i] == target) { idx = i; break; }\n}' },
  { name: 'continue', kind: 'keyword', sig: 'continue;', doc: 'Skip to the next iteration of the innermost loop (in a `for`, the step expression still runs).', example: 'for (int i = 0; i < n; i++) {\n    if (a[i] < 0) continue;\n    sum += a[i];\n}' },
  { name: 'goto', kind: 'keyword', sig: 'goto label;', doc: 'Jump to `label:` in the same function. Occasionally handy for breaking out of nested loops or centralised cleanup.', example: 'if (!buf) goto cleanup;\n/* ... */\ncleanup:\n    free(buf);' },
  { name: 'struct', kind: 'keyword', sig: 'struct Name { fields; };', doc: 'Aggregate type. Access fields with `.` on a value and `->` through a pointer. LeetCode predefines e.g. `struct ListNode` and `struct TreeNode`.', example: 'struct Point { int x, y; };\nstruct Point p = { 1, 2 };\nstruct Point *q = &p; q->x = 5;', insert: 'struct ${1:Name} {\n\t$0\n};' },
  { name: 'typedef', kind: 'keyword', sig: 'typedef existing_type NewName;', doc: 'Create a type alias. Commonly `typedef struct { ... } Name;` so you can skip writing `struct`.', example: 'typedef long long ll;\ntypedef struct { int key, val; } Pair;' },
  { name: 'union', kind: 'keyword', sig: 'union Name { members; };', doc: 'Like a struct but all members share the same storage; only one is valid at a time.', example: 'union Value { int i; float f; };\nunion Value v;\nv.f = 1.5f;  // only the last-written member is valid' },
  { name: 'enum', kind: 'keyword', sig: 'enum Name { A, B, C };', doc: 'Named integer constants, numbered from 0 unless assigned. Values have type `int`.', example: 'enum Dir { UP, RIGHT, DOWN, LEFT };' },
  { name: 'sizeof', kind: 'keyword', sig: 'sizeof(type_or_expr)', doc: 'Size in bytes (type `size_t`), computed at compile time. Gotcha: on an array *parameter* it gives the pointer size, not the array length — pass the length separately.', example: 'int *a = malloc(n * sizeof(int));\nint len = sizeof(arr) / sizeof(arr[0]); // only for real arrays' },
  { name: 'static', kind: 'keyword', sig: 'static type name;', doc: 'At file scope: internal linkage (private to the file). Inside a function: the variable keeps its value between calls. Gotcha on judges: static/global state persists across test cases — reset it.', example: 'int next_id(void) {\n    static int counter = 0;  // keeps its value between calls\n    return ++counter;\n}' },
  { name: 'const', kind: 'keyword', sig: 'const type name', doc: 'Read-only qualifier. `const int *p` = pointer to const int; `int *const p` = const pointer. qsort comparators take `const void *`.', example: 'const int MAX_N = 100;\nsize_t len(const char *s);  // promises not to modify *s' },
  { name: 'extern', kind: 'keyword', sig: 'extern type name;', doc: 'Declares a variable/function defined elsewhere (another translation unit).', example: 'extern int g_count;  // defined in another .c file\ng_count++;' },
  { name: 'volatile', kind: 'keyword', sig: 'volatile type name', doc: 'Tells the compiler the value may change outside program control; prevents caching in registers. Rarely needed in algorithm code.', example: 'volatile int done = 0;  // re-read from memory every access\nwhile (!done) { }' },
  { name: 'inline', kind: 'keyword', sig: 'static inline type f(args)', doc: 'Hint to inline a small function. Use `static inline` for helpers in a single file.', example: 'static inline int max2(int a, int b) {\n    return a > b ? a : b;\n}' },
  { name: 'register', kind: 'keyword', sig: 'register type name;', doc: 'Obsolete hint to keep a variable in a register; compilers ignore it. You cannot take its address.', example: 'register int i;  // a hint only; you cannot take &i' },
  { name: 'void', kind: 'keyword', sig: 'void', doc: 'No value / no type. `void f(void)` takes no args; `void *` is a generic pointer (what `malloc` returns).', example: 'void greet(void) {\n    puts("hi");\n}' },
  { name: 'int', kind: 'type', sig: 'int', doc: 'Signed integer, 32-bit on all mainstream platforms (range ±2.1e9, see `INT_MAX`). Overflow is undefined behaviour — use `long long` for big sums/products.', example: 'int count = 0;\nint a[10];' },
  { name: 'char', kind: 'type', sig: 'char', doc: '1-byte character type. Signedness is implementation-defined; cast to `unsigned char` before passing to `<ctype.h>` functions. Strings are `char` arrays terminated by `\'\\0\'`.', example: 'char c = \'A\';\nchar name[32] = "Ada";' },
  { name: 'short', kind: 'type', sig: 'short', doc: 'Signed integer, at least 16 bits.', example: 'short s = 1000;' },
  { name: 'long', kind: 'type', sig: 'long', doc: 'Signed integer of at least 32 bits — 64-bit on Linux/macOS but 32-bit on Windows. Prefer `long long` for guaranteed 64 bits.', example: 'long total = 0L;' },
  { name: 'long long', kind: 'type', sig: 'long long', doc: 'Signed integer, at least 64 bits (±9.2e18, see `LLONG_MAX`). Print with `%lld`. Cast before multiplying: `(long long)a * b`, otherwise the product overflows as `int`.', example: 'long long prod = (long long)a * b;\nprintf("%lld\\n", prod);' },
  { name: 'unsigned', kind: 'keyword', sig: 'unsigned int', doc: 'Unsigned integer modifier; wraps around modulo 2^N instead of overflowing. Gotcha: `size_t i; i >= 0` is always true, and mixing signed/unsigned in comparisons converts -1 to a huge value.', example: 'unsigned int mask = 0xFFu;\nunsigned char byte = 255;' },
  { name: 'signed', kind: 'keyword', sig: 'signed type', doc: 'Explicit signed modifier (default for `int`; makes `signed char` unambiguous).', example: 'signed char delta = -5;' },
  { name: 'float', kind: 'type', sig: 'float', doc: '32-bit IEEE float (~7 digits). Prefer `double` for accuracy.', example: 'float ratio = 0.75f;' },
  { name: 'double', kind: 'type', sig: 'double', doc: '64-bit IEEE float (~15–16 digits). Print with `%f` / `%.6f`, read with `%lf`. Don\'t compare with `==`; use an epsilon.', example: 'double avg = (double)sum / n;' },
  { name: 'size_t', kind: 'type', sig: 'size_t', doc: 'Unsigned type returned by `sizeof` and `strlen`. Print with `%zu`. Beware underflow: `strlen(s) - 1` when empty is huge.', header: '#include <stddef.h>', example: 'size_t len = strlen(s);\nfor (size_t i = 0; i < len; i++) { /* ... */ }' },
  { name: '#include', kind: 'directive', sig: '#include <header.h>', doc: 'Insert a header. `<...>` for system headers, `"..."` for local files.', insert: '#include <${1:stdio}.h>', example: '#include <stdio.h>\n#include "mylib.h"' },
  { name: '#define', kind: 'directive', sig: '#define NAME value', doc: 'Preprocessor macro (text substitution). Parenthesise macro args and bodies: `#define MAX(a,b) ((a) > (b) ? (a) : (b))` — and beware double evaluation of side effects.', insert: '#define ${1:NAME} ${2:value}', example: '#define N 1000\nint grid[N][N];' },
  { name: 'main', kind: 'function', sig: 'int main(int argc, char **argv)', params: [{ label: 'argc', doc: 'number of command-line args' }, { label: 'argv', doc: 'array of argument strings' }], doc: 'Program entry point. Return 0 for success. `int main(void)` is fine when you ignore arguments.', insert: 'int main(void) {\n\t$0\n\treturn 0;\n}', returns: 'int — exit status: 0 (EXIT_SUCCESS) for success, non-zero for failure', example: 'int main(int argc, char **argv) {\n    printf("%d args\\n", argc - 1);\n    return 0;\n}' },

  // ───────────── stdio.h ─────────────
  { name: 'printf', kind: 'function', sig: 'int printf(const char *format, ...)', params: [{ label: 'format', doc: 'format string with % specifiers' }], doc: 'Formatted output to stdout. Specifiers: `%d` int, `%lld` long long, `%u` unsigned, `%zu` size_t, `%ld` long, `%f` double, `%.2f` 2 decimals, `%c` char, `%s` string, `%p` pointer, `%x` hex, `%%` literal %. Mismatched specifier is undefined behaviour.', example: 'printf("%d %lld %.3f %s\\n", n, big, x, s);', insert: 'printf("${1:%d}\\n", ${2:x});', header: '#include <stdio.h>', returns: 'int — number of characters written, or a negative value on error', learn: {
    summary: "print formatted text",
    what: "printf (\"print formatted\") writes text to standard output. The first argument is a format string: ordinary characters are printed as they are, and each placeholder starting with % is replaced by the next extra argument: %d for an int, %s for a string, %c for a char, %f for a double, %lld for a long long. Nothing ends the line for you; put \\n (newline) in the format wherever you want a line break.",
    params: {
      format: "the text to print, with % placeholders, in double quotes, e.g. \"x = %d\\n\"",
      "...": "the values that fill the placeholders, in order, e.g. x. Their number and types must match the placeholders"
    },
    returns: "The number of characters printed (negative on error). Almost always ignored.",
    example: "int apples = 3;                        // a value to show\nprintf(\"apples: %d\\n\", apples);        // apples: 3\nprintf(\"%s has %d legs\\n\", \"cat\", 4);  // cat has 4 legs\nprintf(\"%.2f\\n\", 3.14159);             // 3.14 (two decimals)",
    watch: [
      "Forgetting \\n at the end leaves the line unfinished; the expected output usually includes it.",
      "A placeholder that doesn't match its argument (e.g. %d with a double) prints garbage. The compiler warns: read the warnings.",
      "To print a literal % sign, write %%."
    ]
  }  },
  { name: 'scanf', kind: 'function', sig: 'int scanf(const char *format, ...)', params: [{ label: 'format', doc: 'format string with % specifiers' }], doc: 'Formatted input from stdin; pass **addresses** (`&x`) except for char arrays. Returns number of items read, or `EOF`. `%d` int, `%lld` long long, `%lf` double (not `%f`!), `%s` word (no spaces), `" %c"` skips whitespace first.', example: 'int n; long long x;\nscanf("%d %lld", &n, &x);\nwhile (scanf("%d", &v) == 1) { ... }', header: '#include <stdio.h>', returns: 'int — number of items successfully assigned, or EOF if input ends before the first conversion', learn: {
    summary: "read formatted values from input",
    what: "scanf reads from standard input and converts the text into values, guided by a format string with placeholders like printf's: %d reads an int, %lld a long long, %lf a double, %s one word, %c one character. Each placeholder except %c first skips whitespace (spaces and newlines), so values may be separated by spaces or line breaks. Because scanf has to store into your variables, you pass their addresses with & (the \"address-of\" operator) so it knows where to write.",
    params: {
      format: "the placeholders describing what to read, e.g. \"%d %lf\"",
      "...": "the addresses of the variables to fill, in order, e.g. &count, &price. A char array is already an address, so it needs no &"
    },
    returns: "How many values were successfully read and stored, or EOF (-1) if the input ended first. Check it: if (scanf(\"%d\", &n) == 1) ...",
    example: "char item[32]; double price;               // where the values go\nif (scanf(\"%31s %lf\", item, &price) == 2)  // read a word, then a number\n    printf(\"%s: %.2f\\n\", item, price);     // e.g. tea: 1.50",
    watch: [
      "Forgetting & (scanf(\"%d\", n)) passes the value instead of its address and usually crashes.",
      "Use %lf (not %f) for a double in scanf, and %lld for long long.",
      "Plain %s stops at the first space and can overflow; give a width such as %31s for a 32-byte array."
    ]
  }  },
  { name: 'puts', kind: 'function', sig: 'int puts(const char *s)', params: [{ label: 's', doc: 'null-terminated string' }], doc: 'Write *s* plus a newline to stdout. Faster than `printf("%s\\n", s)`.', header: '#include <stdio.h>', returns: 'int — a non-negative value on success, or EOF on error', example: 'puts("Hello, world!");  // prints with a trailing newline' },
  { name: 'putchar', kind: 'function', sig: 'int putchar(int c)', params: [{ label: 'c', doc: 'character to write' }], doc: 'Write one character to stdout.', header: '#include <stdio.h>', returns: 'int — the character written (as unsigned char), or EOF on error', example: 'for (int i = 0; i < 3; i++)\n    putchar(\'*\');\nputchar(\'\\n\');' },
  { name: 'getchar', kind: 'function', sig: 'int getchar(void)', doc: 'Read one character from stdin; returns `EOF` at end. Store the result in an `int`, not `char`, so `EOF` is distinguishable.', example: 'int c;\nwhile ((c = getchar()) != EOF) { ... }', header: '#include <stdio.h>', returns: 'int — the next character as unsigned char converted to int, or EOF at end of input / error' },
  { name: 'fgets', kind: 'function', sig: 'char *fgets(char *buf, int n, FILE *stream)', params: [{ label: 'buf', doc: 'destination buffer' }, { label: 'n', doc: 'buffer size (reads at most n-1 chars)' }, { label: 'stream', doc: 'input stream, usually stdin' }], doc: 'Read a line safely (bounded). Keeps the trailing `\\n` if it fits — strip with `buf[strcspn(buf, "\\n")] = 0;`. Returns NULL on EOF.', example: 'char line[256];\nif (fgets(line, sizeof line, stdin))\n    line[strcspn(line, "\\n")] = 0;', header: '#include <stdio.h>', returns: 'char * — buf on success, or NULL at end of file / error with nothing read', learn: {
    summary: "read one line of text safely",
    what: "fgets reads one line from a stream (usually stdin) into a character array that you provide. It stops after the newline, at the end of the input, or when the array is full, whichever comes first, so it can never write past the end of your buffer; that is what makes it \"safe\". The result is a normal C string ending in '\\0'. If the whole line fit, the newline character \\n is kept at the end of the string.",
    params: {
      buf: "the char array that receives the line: declare char line[256]; and pass line",
      n: "the size of that array, e.g. sizeof line. fgets stores at most n-1 characters plus the terminating '\\0'",
      stream: "where to read from: pass stdin for the program's input"
    },
    returns: "buf (the same pointer you passed) on success, or NULL if nothing could be read because the input had ended. Use it as a test: if (fgets(line, sizeof line, stdin) != NULL) { ... }.",
    example: "char line[100];                            // room for 99 chars + '\\0'\nif (fgets(line, sizeof line, stdin)) {     // read a line; NULL means no input\n    printf(\"%zu bytes\\n\", strlen(line));   // the count includes the '\\n'\n}",
    watch: [
      "The trailing \\n is kept: \"cat\" arrives as \"cat\\n\". Remove it with line[strcspn(line, \"\\n\")] = 0;",
      "A line longer than the buffer is cut: the rest stays waiting for the next read.",
      "Pass the real buffer size; sizeof only works on an actual array, not on a pointer."
    ]
  }  },
  { name: 'fputs', kind: 'function', sig: 'int fputs(const char *s, FILE *stream)', params: [{ label: 's', doc: 'string' }, { label: 'stream', doc: 'output stream' }], doc: 'Write *s* to *stream* without adding a newline.', header: '#include <stdio.h>', returns: 'int — a non-negative value on success, or EOF on error', example: 'fputs("error: bad input\\n", stderr);' },
  { name: 'fprintf', kind: 'function', sig: 'int fprintf(FILE *stream, const char *format, ...)', params: [{ label: 'stream', doc: 'output stream, e.g. stderr' }, { label: 'format', doc: 'format string' }], doc: 'Like `printf` but to a given stream. `fprintf(stderr, ...)` for debug output that does not pollute stdout.', header: '#include <stdio.h>', returns: 'int — number of characters written, or a negative value on error', example: 'fprintf(stderr, "bad value: %d\\n", x);' },
  { name: 'sprintf', kind: 'function', sig: 'int sprintf(char *buf, const char *format, ...)', params: [{ label: 'buf', doc: 'destination buffer' }, { label: 'format', doc: 'format string' }], doc: 'Format into a buffer; returns chars written. **Unbounded** — can overflow *buf*; prefer `snprintf`.', header: '#include <stdio.h>', returns: 'int — number of characters written (excluding the terminating \'\\0\')', example: 'char buf[32];\nsprintf(buf, "%d-%d", a, b);', learn: {
    summary: "print formatted text into a string",
    what: "sprintf works exactly like printf, but instead of showing the text it writes it into a character array you provide, ending with '\\0'. Use it to build strings out of numbers and other values, for example turning an int into its decimal digits or assembling a label. It returns how many characters it wrote, which tells you where the text ends.",
    params: {
      buf: "the char array to write into; it must be big enough for the whole result plus the '\\0'",
      format: "the template with % placeholders, as in printf, e.g. \"img_%03d.png\"",
      "...": "the values for the placeholders, in order"
    },
    returns: "The number of characters written, not counting the '\\0'. buf + that number points just past the text.",
    example: "char name[32];                             // destination buffer\nint n = sprintf(name, \"img_%03d.png\", 7);  // name is now \"img_007.png\"\nprintf(\"%s (%d chars)\\n\", name, n);        // img_007.png (11 chars)",
    watch: [
      "No bounds checking: a result longer than buf overwrites other memory. snprintf(buf, sizeof buf, ...) is the safe variant.",
      "Don't use the same buffer as both the destination and a %s argument."
    ]
  }  },
  { name: 'snprintf', kind: 'function', sig: 'int snprintf(char *buf, size_t size, const char *format, ...)', params: [{ label: 'buf', doc: 'destination buffer' }, { label: 'size', doc: 'buffer capacity including the terminator' }, { label: 'format', doc: 'format string' }], doc: 'Bounded `sprintf`: always null-terminates (if size > 0). Returns the length that *would* have been written — `snprintf(NULL, 0, ...)` measures.', example: 'char buf[32];\nsnprintf(buf, sizeof buf, "%d->%d", a, b);', header: '#include <stdio.h>', returns: 'int — number of characters that would have been written if size were large enough (excluding \'\\0\'); >= size means truncation' },
  { name: 'sscanf', kind: 'function', sig: 'int sscanf(const char *str, const char *format, ...)', params: [{ label: 'str', doc: 'source string' }, { label: 'format', doc: 'format string' }], doc: 'Like `scanf` but parses from a string. Returns the number of items matched.', example: 'int h, m;\nsscanf("12:34", "%d:%d", &h, &m);', header: '#include <stdio.h>', returns: 'int — number of items successfully assigned, or EOF if input ends before the first conversion' },
  { name: 'EOF', kind: 'constant', sig: '#define EOF (-1)', doc: 'Negative value returned by input functions at end of file or on error.', header: '#include <stdio.h>', example: 'int c;\nwhile ((c = getchar()) != EOF)\n    putchar(c);' },
  { name: 'stdin', kind: 'constant', sig: 'FILE *stdin', doc: 'Standard input stream.', header: '#include <stdio.h>', example: 'char line[256];\nfgets(line, sizeof line, stdin);', learn: {
    summary: "the program's input stream",
    what: "stdin (\"standard input\") is a ready-made variable that stands for where your program's input comes from: the keyboard, or the test data the judge feeds in. It is a stream: think of a queue of characters that you read from the front; once read they are gone, and the next read continues where the last one stopped. Its type, FILE *, is a pointer to the C library's bookkeeping for that stream. You never create or close it; you just pass it to reading functions such as fgets, fgetc or fscanf.",
    example: "int c = fgetc(stdin);           // read one character from the input\nif (c == EOF) return 0;         // EOF means the input has run out\nprintf(\"first char: %c\\n\", c);  // show the character we got",
    watch: [
      "Never fclose(stdin) or assign to it.",
      "Reads that hit the end of input return a special value (EOF for fgetc, NULL for fgets): check for it."
    ]
  }  },
  { name: 'stdout', kind: 'constant', sig: 'FILE *stdout', doc: 'Standard output stream (buffered).', header: '#include <stdio.h>', example: 'fprintf(stdout, "%d\\n", ans);\nfflush(stdout);' },
  { name: 'stderr', kind: 'constant', sig: 'FILE *stderr', doc: 'Standard error stream (unbuffered); use for debug prints.', header: '#include <stdio.h>', example: 'fprintf(stderr, "warning: n=%d\\n", n);' },

  { name: 'FILE', kind: 'type', sig: 'FILE', doc: 'Opaque stream type. You only ever hold a `FILE *` obtained from `fopen` (or `stdin`/`stdout`/`stderr`) and pass it to stdio functions.', example: 'FILE *f = fopen("data.txt", "r");', header: '#include <stdio.h>' },
  { name: 'fopen', kind: 'function', sig: 'FILE *fopen(const char *path, const char *mode)', params: [{ label: 'path', doc: 'file name to open' }, { label: 'mode', doc: '"r" read, "w" write (truncate/create), "a" append; add "b" for binary, "+" for read+write' }], returns: 'FILE * — the opened stream, or NULL on failure (errno set)', doc: 'Open a file and return a stream for it. **Always check for NULL**, and `fclose` the stream when done.', example: 'FILE *f = fopen(path, "r");\nif (!f) { perror(path); return 1; }', insert: 'fopen(${1:path}, "${2:r}")', header: '#include <stdio.h>' },
  { name: 'fclose', kind: 'function', sig: 'int fclose(FILE *stream)', params: [{ label: 'stream', doc: 'stream to close' }], returns: 'int — 0 on success, or EOF on error', doc: 'Flush and close a stream; the pointer is invalid afterwards. Unclosed write streams may lose buffered data.', example: 'fclose(f);\nf = NULL;', header: '#include <stdio.h>' },
  { name: 'fflush', kind: 'function', sig: 'int fflush(FILE *stream)', params: [{ label: 'stream', doc: 'output stream to flush (NULL flushes all output streams)' }], returns: 'int — 0 on success, or EOF on error', doc: 'Write any buffered output to the underlying file now. Useful before a crash-prone section or for interactive prompts printed without a newline. `fflush(stdin)` is undefined behavior.', example: 'printf("Enter n: ");\nfflush(stdout);', header: '#include <stdio.h>' },
  { name: 'fread', kind: 'function', sig: 'size_t fread(void *ptr, size_t size, size_t count, FILE *stream)', params: [{ label: 'ptr', doc: 'destination buffer' }, { label: 'size', doc: 'size of each item in bytes' }, { label: 'count', doc: 'maximum number of items to read' }, { label: 'stream', doc: 'input stream' }], returns: 'size_t — number of complete items read; less than count at end of file or on error', doc: 'Read up to *count* items of *size* bytes each (binary I/O). Use `feof`/`ferror` to tell why it returned short.', example: 'unsigned char buf[4096];\nsize_t got = fread(buf, 1, sizeof buf, f);', header: '#include <stdio.h>' },
  { name: 'fwrite', kind: 'function', sig: 'size_t fwrite(const void *ptr, size_t size, size_t count, FILE *stream)', params: [{ label: 'ptr', doc: 'data to write' }, { label: 'size', doc: 'size of each item in bytes' }, { label: 'count', doc: 'number of items' }, { label: 'stream', doc: 'output stream' }], returns: 'size_t — number of complete items written; less than count means an error', doc: 'Write *count* items of *size* bytes each (binary I/O).', example: 'int a[3] = {1, 2, 3};\nif (fwrite(a, sizeof a[0], 3, f) != 3) perror("fwrite");', header: '#include <stdio.h>' },
  { name: 'fgetc', kind: 'function', sig: 'int fgetc(FILE *stream)', params: [{ label: 'stream', doc: 'input stream' }], returns: 'int — the next character as unsigned char converted to int, or EOF at end of file / error', doc: 'Read one character from *stream*. Store the result in an `int`, not a `char`, so EOF can be distinguished.', example: 'int c;\nwhile ((c = fgetc(f)) != EOF)\n    if (c == \'\\n\') lines++;', header: '#include <stdio.h>' },
  { name: 'fputc', kind: 'function', sig: 'int fputc(int c, FILE *stream)', params: [{ label: 'c', doc: 'character to write' }, { label: 'stream', doc: 'output stream' }], returns: 'int — the character written, or EOF on error', doc: 'Write one character to *stream*.', example: 'fputc(\'\\n\', out);', header: '#include <stdio.h>' },
  { name: 'fscanf', kind: 'function', sig: 'int fscanf(FILE *stream, const char *format, ...)', params: [{ label: 'stream', doc: 'input stream' }, { label: 'format', doc: 'conversion spec like scanf' }], returns: 'int — number of items successfully assigned, or EOF if input ends before the first conversion', doc: 'Like `scanf` but reads from *stream*. Compare the return value with the number of conversions you expect.', example: 'int x, y;\nwhile (fscanf(f, "%d %d", &x, &y) == 2)\n    sum += x * y;', header: '#include <stdio.h>' },
  { name: 'perror', kind: 'function', sig: 'void perror(const char *s)', params: [{ label: 's', doc: 'prefix message (often the file or function name)' }], returns: 'void', doc: 'Print *s*, a colon, and the text for the current `errno` to `stderr`. Call it right after the failing function, before anything else changes `errno`.', example: 'FILE *f = fopen("in.txt", "r");\nif (!f) { perror("in.txt"); return 1; }', header: '#include <stdio.h>' },
  // ───────────── stdlib.h ─────────────
  { name: 'malloc', kind: 'function', sig: 'void *malloc(size_t size)', params: [{ label: 'size', doc: 'bytes to allocate' }], doc: 'Allocate *size* bytes of **uninitialised** heap memory; returns NULL on failure. Always multiply by `sizeof`. LeetCode returns arrays this way and expects you to set `*returnSize`.', example: 'int *res = malloc(n * sizeof(int));\n*returnSize = n;\nreturn res;', insert: 'malloc(${1:n} * sizeof(${2:int}))', header: '#include <stdlib.h>', returns: 'void * — pointer to uninitialized memory, or NULL on failure', learn: {
    summary: "request a block of memory at runtime",
    what: "malloc (\"memory allocate\") asks for a block of size bytes on the heap: memory that stays valid until you free it, unlike local arrays that vanish when their function returns. Use it when a size is only known while the program runs, or when a function must hand an array back to its caller. You get a pointer to the start of the block; its contents are leftover garbage until you write to them. Compute the byte count with sizeof: n * sizeof(int) for n ints.",
    params: {
      size: "the number of bytes wanted, e.g. n * sizeof(int) for an array of n ints"
    },
    returns: "A pointer to the new block (void *, which converts to any pointer type such as int *), or NULL if memory ran out. Release it later with free(ptr).",
    example: "int n = 5;                                  // size decided at runtime\nint *sq = malloc(n * sizeof(int));          // room for 5 ints\nfor (int i = 0; i < n; i++) sq[i] = i * i;  // fill: 0 1 4 9 16\nfree(sq);                                   // give the memory back",
    watch: [
      "malloc(n) gives n bytes, not n ints: multiply by sizeof.",
      "The memory is not zeroed; use calloc when you need zeros.",
      "Every malloc should eventually be matched by exactly one free (unless you return the block to a caller who frees it)."
    ]
  }  },
  { name: 'calloc', kind: 'function', sig: 'void *calloc(size_t count, size_t size)', params: [{ label: 'count', doc: 'number of elements' }, { label: 'size', doc: 'size of each element' }], doc: 'Allocate an array of *count* elements, **zero-initialised**. Great for counters/visited arrays.', example: 'int *cnt = calloc(26, sizeof(int));', insert: 'calloc(${1:n}, sizeof(${2:int}))', header: '#include <stdlib.h>', returns: 'void * — pointer to zero-filled memory, or NULL on failure', learn: {
    summary: "allocate memory already filled with zeros",
    what: "calloc (\"clear allocate\") is like malloc, but you give the element count and element size separately and every byte of the block is set to zero. That makes it ideal for counters, flags and tables that must start empty: an int array from calloc starts as all 0, an array of pointers as all NULL. It also checks that count * size doesn't overflow.",
    params: {
      count: "how many elements, e.g. 26 for one counter per letter",
      size: "the size of one element in bytes, e.g. sizeof(int)"
    },
    returns: "A pointer to the zero-filled block, or NULL if memory ran out. Free it with free(ptr) when done.",
    example: "int *seen = calloc(26, sizeof(int));            // 26 counters, all 0\nconst char *w = \"banana\";                       // text to tally\nfor (int i = 0; w[i]; i++) seen[w[i] - 'a']++;  // count each letter\nprintf(\"%d\\n\", seen['a' - 'a']);                // 3 (three a's)\nfree(seen);                                     // release the memory",
    watch: [
      "Zero means 0 for ints and NULL for pointers. If 0 can be a real value in a table, you need a separate \"empty\" marker.",
      "Still check for NULL and free the block later; zeroed memory is otherwise ordinary heap memory."
    ]
  }  },
  { name: 'realloc', kind: 'function', sig: 'void *realloc(void *ptr, size_t size)', params: [{ label: 'ptr', doc: 'previous allocation (or NULL)' }, { label: 'size', doc: 'new size in bytes' }], doc: 'Resize an allocation, possibly moving it; contents preserved up to the old size. Double capacity for amortised **O(1)** push. On failure returns NULL and the old block is still valid.', example: 'if (len == cap) {\n    cap *= 2;\n    a = realloc(a, cap * sizeof *a);\n}', header: '#include <stdlib.h>', returns: 'void * — pointer to the resized block (may have moved), or NULL on failure (original block still valid)' },
  { name: 'free', kind: 'function', sig: 'void free(void *ptr)', params: [{ label: 'ptr', doc: 'pointer from malloc/calloc/realloc (NULL is a no-op)' }], doc: 'Release heap memory. Don\'t free the array you return to the judge, and never use or free a pointer twice.', header: '#include <stdlib.h>', returns: 'void', example: 'int *a = malloc(n * sizeof *a);\n/* ... use a ... */\nfree(a);\na = NULL;' },
  { name: 'qsort', kind: 'function', sig: 'void qsort(void *base, size_t nmemb, size_t size, int (*compar)(const void *, const void *))', params: [{ label: 'base', doc: 'array to sort' }, { label: 'nmemb', doc: 'number of elements' }, { label: 'size', doc: 'size of each element' }, { label: 'compar', doc: 'returns <0, 0, >0 for a<b, a==b, a>b' }], doc: 'Sort an array in place, **O(n log n)** average, not stable. Gotcha: `return a - b` can overflow — use `(a > b) - (a < b)`.', example: 'int cmp(const void *a, const void *b) {\n    int x = *(const int *)a, y = *(const int *)b; return (x > y) - (x < y);\n}\nqsort(arr, n, sizeof(int), cmp);', insert: 'qsort(${1:arr}, ${2:n}, sizeof(${3:int}), ${4:cmp});', header: '#include <stdlib.h>', returns: 'void (base is sorted in place)', learn: {
    summary: "sort any array with a comparison function",
    what: "qsort sorts an array in place, meaning it rearranges the original array. C has no generics, so qsort doesn't know what your elements are: you tell it where the array starts, how many elements there are, how big each one is, and give it a comparison function. qsort calls that function with pointers to two elements, and the function answers negative if the first should come first, positive if the second should, and 0 if they are equal. Typical time is O(n log n).",
    params: {
      base: "the array to sort, e.g. scores",
      nmemb: "the number of elements, e.g. n",
      size: "the size of one element in bytes, e.g. sizeof scores[0]",
      compar: "the name of your comparison function, e.g. cmp_desc, without parentheses: you pass the function itself"
    },
    returns: "Nothing (void). Afterwards the array is sorted in place.",
    example: "int cmp_desc(const void *a, const void *b) {       // compares two ints\n    int x = *(const int *)a, y = *(const int *)b;  // turn the pointers back into ints\n    return (y > x) - (y < x);                      // bigger first = descending\n}                                                  // end of the comparator\nqsort(scores, n, sizeof scores[0], cmp_desc);      // sort scores high to low",
    watch: [
      "return x - y can overflow for large ints; use (x > y) - (x < y) instead.",
      "The comparator receives pointers to elements, not the elements: cast and dereference them.",
      "size is the size of one element, not of the whole array."
    ]
  }  },
  { name: 'bsearch', kind: 'function', sig: 'void *bsearch(const void *key, const void *base, size_t nmemb, size_t size, int (*compar)(const void *, const void *))', params: [{ label: 'key', doc: 'pointer to the value sought' }, { label: 'base', doc: 'sorted array' }, { label: 'nmemb', doc: 'number of elements' }, { label: 'size', doc: 'element size' }, { label: 'compar', doc: 'same comparator as qsort' }], doc: 'Binary search a sorted array, **O(log n)**. Returns a pointer to *a* matching element or NULL — no lower_bound semantics; hand-roll that.', example: 'int *p = bsearch(&target, arr, n, sizeof(int), cmp);\nif (p) idx = p - arr;', header: '#include <stdlib.h>', returns: 'void * — pointer to a matching element, or NULL if not found' },
  { name: 'abs', kind: 'function', sig: 'int abs(int n)', params: [{ label: 'n', doc: 'integer' }], doc: 'Absolute value of an `int`. `abs(INT_MIN)` overflows. Use `llabs` for long long and `fabs` for double.', header: '#include <stdlib.h>', returns: 'int — |n| (undefined for INT_MIN)', example: 'int d = abs(a - b);' },
  { name: 'labs', kind: 'function', sig: 'long labs(long n)', params: [{ label: 'n', doc: 'long integer' }], doc: 'Absolute value of a `long`.', header: '#include <stdlib.h>', returns: 'long — |n|', example: 'long d = labs(x - y);' },
  { name: 'llabs', kind: 'function', sig: 'long long llabs(long long n)', params: [{ label: 'n', doc: 'long long integer' }], doc: 'Absolute value of a `long long`.', header: '#include <stdlib.h>', returns: 'long long — |n|', example: 'long long d = llabs(x - y);' },
  { name: 'atoi', kind: 'function', sig: 'int atoi(const char *s)', params: [{ label: 's', doc: 'numeric string' }], doc: 'Parse an int, skipping leading whitespace. No error reporting (returns 0 on garbage) and overflow is UB — `strtol` is safer.', header: '#include <stdlib.h>', returns: 'int — the parsed value, or 0 if no digits (errors undetectable)', example: 'int n = atoi(argv[1]);' },
  { name: 'atol', kind: 'function', sig: 'long atol(const char *s)', params: [{ label: 's', doc: 'numeric string' }], doc: 'Parse a long. No error reporting.', header: '#include <stdlib.h>', returns: 'long — the parsed value, or 0 if no digits', example: 'long n = atol("123456");' },
  { name: 'atoll', kind: 'function', sig: 'long long atoll(const char *s)', params: [{ label: 's', doc: 'numeric string' }], doc: 'Parse a long long. No error reporting.', header: '#include <stdlib.h>', returns: 'long long — the parsed value, or 0 if no digits', example: 'long long big = atoll("9000000000");' },
  { name: 'atof', kind: 'function', sig: 'double atof(const char *s)', params: [{ label: 's', doc: 'numeric string' }], doc: 'Parse a double. No error reporting; see `strtod`.', header: '#include <stdlib.h>', returns: 'double — the parsed value, or 0.0 if no number', example: 'double x = atof("3.14");' },
  { name: 'strtol', kind: 'function', sig: 'long strtol(const char *s, char **endptr, int base)', params: [{ label: 's', doc: 'string to parse' }, { label: 'endptr', doc: 'receives pointer past the last parsed char (or NULL)' }, { label: 'base', doc: '2..36, or 0 to auto-detect 0x/0 prefixes' }], doc: 'Parse a long in any base, with error detection via *endptr* and `errno` (ERANGE, clamps to LONG_MAX/LONG_MIN).', example: 'char *end;\nlong v = strtol(s, &end, 10);\nif (end == s) { /* no digits */ }', header: '#include <stdlib.h>', returns: 'long — the parsed value; 0 if nothing parsed; LONG_MAX/LONG_MIN with errno = ERANGE on overflow' },
  { name: 'strtoll', kind: 'function', sig: 'long long strtoll(const char *s, char **endptr, int base)', params: [{ label: 's', doc: 'string to parse' }, { label: 'endptr', doc: 'receives end pointer (or NULL)' }, { label: 'base', doc: 'numeric base, 0 = auto' }], doc: 'Like `strtol` but returns `long long`. Handy for walking a string of numbers by reusing *endptr*.', header: '#include <stdlib.h>', returns: 'long long — the parsed value; LLONG_MAX/LLONG_MIN with errno = ERANGE on overflow', example: 'char *end;\nlong long v = strtoll(s, &end, 10);\nif (end == s) puts("not a number");' },
  { name: 'strtoul', kind: 'function', sig: 'unsigned long strtoul(const char *s, char **endptr, int base)', params: [{ label: 's', doc: 'string to parse' }, { label: 'endptr', doc: 'receives end pointer (or NULL)' }, { label: 'base', doc: 'numeric base' }], doc: 'Parse an unsigned long. Note: a leading `-` is accepted and negated (wraps).', header: '#include <stdlib.h>', returns: 'unsigned long — the parsed value; ULONG_MAX with errno = ERANGE on overflow', example: 'unsigned long mask = strtoul("ff", NULL, 16);  // 255' },
  { name: 'strtod', kind: 'function', sig: 'double strtod(const char *s, char **endptr)', params: [{ label: 's', doc: 'string to parse' }, { label: 'endptr', doc: 'receives end pointer (or NULL)' }], doc: 'Parse a double with end-pointer error detection.', header: '#include <stdlib.h>', returns: 'double — the parsed value; *endptr points past the last character used', example: 'char *end;\ndouble x = strtod("2.5kg", &end);  // x = 2.5, end -> "kg"' },
  { name: 'exit', kind: 'function', sig: 'void exit(int status)', params: [{ label: 'status', doc: 'EXIT_SUCCESS (0) or EXIT_FAILURE' }], doc: 'Terminate the program, flushing stdio buffers.', header: '#include <stdlib.h>', returns: 'void — does not return', example: 'if (!buf) {\n    perror("malloc");\n    exit(EXIT_FAILURE);\n}' },
  { name: 'rand', kind: 'function', sig: 'int rand(void)', doc: 'Pseudo-random int in [0, `RAND_MAX`] (RAND_MAX may be only 32767). `rand() % k` is slightly biased. Seed with `srand`.', example: 'int r = lo + rand() % (hi - lo + 1);', header: '#include <stdlib.h>', returns: 'int — a pseudo-random value in [0, RAND_MAX]' },
  { name: 'srand', kind: 'function', sig: 'void srand(unsigned int seed)', params: [{ label: 'seed', doc: 'seed value' }], doc: 'Seed `rand`. Call once, e.g. `srand(time(NULL))` (needs `<time.h>`).', header: '#include <stdlib.h>', returns: 'void', example: 'srand((unsigned)time(NULL));\nint dice = rand() % 6 + 1;' },
  { name: 'RAND_MAX', kind: 'constant', sig: '#define RAND_MAX ...', doc: 'Largest value `rand()` returns (≥ 32767; 2147483647 on glibc/macOS).', header: '#include <stdlib.h>', example: 'double u = (double)rand() / RAND_MAX;  // in [0, 1]' },
  { name: 'EXIT_SUCCESS', kind: 'constant', sig: '#define EXIT_SUCCESS 0', doc: 'Successful exit status.', header: '#include <stdlib.h>', example: 'return EXIT_SUCCESS;' },
  { name: 'EXIT_FAILURE', kind: 'constant', sig: '#define EXIT_FAILURE 1', doc: 'Unsuccessful exit status.', header: '#include <stdlib.h>', example: 'if (argc < 2) return EXIT_FAILURE;' },
  { name: 'NULL', kind: 'constant', sig: '#define NULL ((void *)0)', doc: 'Null pointer constant. Check `malloc` results and list/tree pointers against it: `while (node != NULL)` or just `while (node)`.', header: '#include <stddef.h>', example: 'int *p = NULL;\nif (p == NULL) puts("no data");' },

  { name: 'abort', kind: 'function', sig: 'void abort(void)', returns: 'void — does not return', doc: 'Terminate the program abnormally (raises `SIGABRT`) without running `atexit` handlers or flushing streams. Used for "can\'t happen" situations; `assert` calls it on failure.', example: 'if (state < 0 || state > 3)\n    abort();  // impossible state', header: '#include <stdlib.h>' },
  // ───────────── string.h ─────────────
  { name: 'strlen', kind: 'function', sig: 'size_t strlen(const char *s)', params: [{ label: 's', doc: 'null-terminated string' }], doc: 'Length excluding the terminator — **O(n)** each call! Hoist it out of loop conditions: `for (int i = 0, n = strlen(s); i < n; i++)`.', header: '#include <string.h>', returns: 'size_t — number of characters before the terminating \'\\0\'', example: 'size_t n = strlen(s);\nif (n > 0 && s[n - 1] == \'\\n\') s[n - 1] = \'\\0\';' },
  { name: 'strcpy', kind: 'function', sig: 'char *strcpy(char *dest, const char *src)', params: [{ label: 'dest', doc: 'destination buffer (must be large enough)' }, { label: 'src', doc: 'source string' }], doc: 'Copy *src* including the terminator. **No bounds check** — overflow if *dest* is too small (needs strlen(src)+1 bytes).', header: '#include <string.h>', returns: 'char * — dest', example: 'char dst[16];\nstrcpy(dst, "hello");  // dst must be large enough' },
  { name: 'strncpy', kind: 'function', sig: 'char *strncpy(char *dest, const char *src, size_t n)', params: [{ label: 'dest', doc: 'destination buffer' }, { label: 'src', doc: 'source string' }, { label: 'n', doc: 'max chars to copy' }], doc: 'Copy at most *n* chars. Gotcha: does **not** null-terminate if src has ≥ n chars — set `dest[n] = 0` yourself; pads with zeros otherwise.', header: '#include <string.h>', returns: 'char * — dest (not \'\\0\'-terminated if src has n or more chars)', example: 'char name[8];\nstrncpy(name, src, sizeof name - 1);\nname[sizeof name - 1] = \'\\0\';' },
  { name: 'strcmp', kind: 'function', sig: 'int strcmp(const char *a, const char *b)', params: [{ label: 'a', doc: 'first string' }, { label: 'b', doc: 'second string' }], doc: 'Lexicographic compare: <0, 0, >0. Strings are equal when it returns **0** — `if (strcmp(a, b) == 0)`. `a == b` only compares pointers.', header: '#include <string.h>', returns: 'int — < 0, 0, or > 0 as a sorts before, equal to, or after b', example: 'if (strcmp(cmd, "quit") == 0)\n    running = false;' },
  { name: 'strncmp', kind: 'function', sig: 'int strncmp(const char *a, const char *b, size_t n)', params: [{ label: 'a', doc: 'first string' }, { label: 'b', doc: 'second string' }, { label: 'n', doc: 'max chars to compare' }], doc: 'Compare up to *n* chars; useful for prefix checks: `strncmp(s, "abc", 3) == 0`.', header: '#include <string.h>', returns: 'int — < 0, 0, or > 0 comparing at most n characters', example: 'if (strncmp(line, "GET ", 4) == 0)\n    handle_get(line + 4);' },
  { name: 'strcat', kind: 'function', sig: 'char *strcat(char *dest, const char *src)', params: [{ label: 'dest', doc: 'null-terminated buffer with room' }, { label: 'src', doc: 'string to append' }], doc: 'Append *src* to *dest*. **O(len(dest)+len(src))** — repeated strcat in a loop is quadratic; track an end index instead. No bounds check.', header: '#include <string.h>', returns: 'char * — dest', example: 'char path[64] = "/tmp/";\nstrcat(path, "out.txt");' },
  { name: 'strncat', kind: 'function', sig: 'char *strncat(char *dest, const char *src, size_t n)', params: [{ label: 'dest', doc: 'destination' }, { label: 'src', doc: 'source' }, { label: 'n', doc: 'max chars to append' }], doc: 'Append at most *n* chars and always null-terminate (dest needs strlen(dest)+n+1 bytes).', header: '#include <string.h>', returns: 'char * — dest (always \'\\0\'-terminated)', example: 'char buf[16] = "id:";\nstrncat(buf, s, sizeof buf - strlen(buf) - 1);' },
  { name: 'strchr', kind: 'function', sig: 'char *strchr(const char *s, int c)', params: [{ label: 's', doc: 'string to search' }, { label: 'c', doc: 'character to find' }], doc: 'Pointer to the first occurrence of *c*, or NULL. Index = `p - s`.', header: '#include <string.h>', returns: 'char * — pointer to the first occurrence of c, or NULL if not found', example: 'char *eq = strchr(line, \'=\');\nif (eq) *eq = \'\\0\';  // split key=value' },
  { name: 'strrchr', kind: 'function', sig: 'char *strrchr(const char *s, int c)', params: [{ label: 's', doc: 'string to search' }, { label: 'c', doc: 'character to find' }], doc: 'Pointer to the last occurrence of *c*, or NULL.', header: '#include <string.h>', returns: 'char * — pointer to the last occurrence of c, or NULL if not found', example: 'char *dot = strrchr(filename, \'.\');\nif (dot) printf("ext: %s\\n", dot + 1);' },
  { name: 'strstr', kind: 'function', sig: 'char *strstr(const char *haystack, const char *needle)', params: [{ label: 'haystack', doc: 'string to search in' }, { label: 'needle', doc: 'substring to find' }], doc: 'Pointer to the first occurrence of *needle*, or NULL. Empty needle returns haystack.', header: '#include <string.h>', returns: 'char * — pointer to the first occurrence of needle, or NULL if not found', example: 'if (strstr(line, "error") != NULL)\n    errors++;' },
  { name: 'strdup', kind: 'function', sig: 'char *strdup(const char *s)', params: [{ label: 's', doc: 'string to copy' }], doc: 'Return a `malloc`-ed copy of *s* (POSIX; standard in C23). Caller must `free` it.', header: '#include <string.h>', returns: 'char * — a malloc\'d copy (free it), or NULL on failure', example: 'char *copy = strdup(s);\n/* ... */\nfree(copy);' },
  { name: 'strndup', kind: 'function', sig: 'char *strndup(const char *s, size_t n)', params: [{ label: 's', doc: 'string to copy' }, { label: 'n', doc: 'max chars' }], doc: 'Malloc-ed copy of at most *n* chars, always null-terminated — handy for substrings.', header: '#include <string.h>', returns: 'char * — a malloc\'d copy of at most n chars, \'\\0\'-terminated, or NULL on failure', example: 'char *word = strndup(s + start, len);\nfree(word);' },
  { name: 'strtok', kind: 'function', sig: 'char *strtok(char *str, const char *delim)', params: [{ label: 'str', doc: 'string to split (NULL on later calls)' }, { label: 'delim', doc: 'set of delimiter characters' }], doc: 'Split a string into tokens, **modifying** it. Pass the string first, then NULL to continue. Not reentrant; can\'t be used on string literals.', example: 'for (char *t = strtok(s, " "); t; t = strtok(NULL, " "))\n    puts(t);', header: '#include <string.h>', returns: 'char * — pointer to the next token, or NULL when no tokens remain' },
  { name: 'strspn', kind: 'function', sig: 'size_t strspn(const char *s, const char *accept)', params: [{ label: 's', doc: 'string' }, { label: 'accept', doc: 'allowed characters' }], doc: 'Length of the initial run of *s* made only of chars in *accept*.', header: '#include <string.h>', returns: 'size_t — length of the leading run of characters that are all in accept', example: 'size_t ws = strspn(s, " \\t");  // count leading blanks' },
  { name: 'strcspn', kind: 'function', sig: 'size_t strcspn(const char *s, const char *reject)', params: [{ label: 's', doc: 'string' }, { label: 'reject', doc: 'stop characters' }], doc: 'Length of the initial run of *s* containing none of *reject*. Idiom to strip a newline: `s[strcspn(s, "\\n")] = 0;`.', header: '#include <string.h>', returns: 'size_t — length of the leading run containing no character from reject', example: 'buf[strcspn(buf, "\\n")] = \'\\0\';  // strip newline from fgets', learn: {
    summary: "count characters before any listed one",
    what: "strcspn scans the string s from the start and counts how many characters go by before it reaches any character that appears in reject. In other words it returns the index of the first \"stop\" character, or the length of s if none appears. Its most common job is finding the newline that fgets leaves at the end of a line, so you can cut the string there by writing a '\\0' (the end-of-string marker) at that index.",
    params: {
      s: "the string to scan, e.g. \"abc123\"",
      reject: "a string listing the characters to stop at, e.g. \"0123456789\" (any digit) or \"\\n\" (a newline)"
    },
    returns: "A size_t (a non-negative count): the position of the first matching character, or strlen(s) if there is none. Use it as an index into s.",
    example: "const char *code = \"abc123\";             // a sample string\nsize_t i = strcspn(code, \"0123456789\");  // stop at the first digit\nprintf(\"%zu\\n\", i);                      // 3: \"abc\" comes before '1'\nchar pair[] = \"key;value\";               // a writable copy\npair[strcspn(pair, \";\")] = 0;            // cut at ';' -> pair is \"key\"",
    watch: [
      "reject is a set of characters, not a word: strcspn(s, \"ab\") stops at the first a or b.",
      "It returns a count, not a pointer: use it as s[i]."
    ]
  }  },
  { name: 'memset', kind: 'function', sig: 'void *memset(void *ptr, int value, size_t n)', params: [{ label: 'ptr', doc: 'memory to fill' }, { label: 'value', doc: 'byte value (converted to unsigned char)' }, { label: 'n', doc: 'number of bytes' }], doc: 'Fill *n* **bytes**. Works for 0 and -1 on int arrays, but `memset(a, 1, n*sizeof(int))` makes each int 0x01010101, not 1.', example: 'memset(dp, 0, sizeof(int) * n);\nmemset(dist, 0x3f, sizeof dist); // ~1e9 "infinity"', header: '#include <string.h>', returns: 'void * — ptr' },
  { name: 'memcpy', kind: 'function', sig: 'void *memcpy(void *dest, const void *src, size_t n)', params: [{ label: 'dest', doc: 'destination' }, { label: 'src', doc: 'source' }, { label: 'n', doc: 'bytes to copy' }], doc: 'Copy *n* bytes. Regions must **not overlap** — use `memmove` if they might.', example: 'memcpy(copy, arr, n * sizeof(int));', header: '#include <string.h>', returns: 'void * — dest' },
  { name: 'memmove', kind: 'function', sig: 'void *memmove(void *dest, const void *src, size_t n)', params: [{ label: 'dest', doc: 'destination' }, { label: 'src', doc: 'source' }, { label: 'n', doc: 'bytes to copy' }], doc: 'Copy *n* bytes, safe for overlapping regions (e.g. shifting elements within one array).', example: 'memmove(a + i + 1, a + i, (n - i) * sizeof(int)); // insert gap', header: '#include <string.h>', returns: 'void * — dest' },
  { name: 'memcmp', kind: 'function', sig: 'int memcmp(const void *a, const void *b, size_t n)', params: [{ label: 'a', doc: 'first block' }, { label: 'b', doc: 'second block' }, { label: 'n', doc: 'bytes to compare' }], doc: 'Byte-wise compare; 0 if equal. Handy for comparing count arrays (anagrams): `memcmp(c1, c2, sizeof c1) == 0`.', header: '#include <string.h>', returns: 'int — < 0, 0, or > 0 comparing the first n bytes', example: 'if (memcmp(a, b, n * sizeof(int)) == 0)\n    puts("arrays equal");' },

  // ───────────── ctype.h ─────────────
  { name: 'isalpha', kind: 'function', sig: 'int isalpha(int c)', params: [{ label: 'c', doc: 'character (as unsigned char or EOF)' }], doc: 'Non-zero if *c* is a letter. Returns non-zero, not necessarily 1.', header: '#include <ctype.h>', returns: 'int — non-zero if c is a letter, else 0', example: 'if (isalpha((unsigned char)s[i]))\n    letters++;' },
  { name: 'isdigit', kind: 'function', sig: 'int isdigit(int c)', params: [{ label: 'c', doc: 'character' }], doc: 'Non-zero if *c* is `\'0\'`..`\'9\'`. Digit value: `c - \'0\'`.', header: '#include <ctype.h>', returns: 'int — non-zero if c is \'0\'–\'9\', else 0', example: 'if (isdigit((unsigned char)c))\n    num = num * 10 + (c - \'0\');' },
  { name: 'isalnum', kind: 'function', sig: 'int isalnum(int c)', params: [{ label: 'c', doc: 'character' }], doc: 'Non-zero if *c* is a letter or digit (e.g. valid-palindrome filtering).', header: '#include <ctype.h>', returns: 'int — non-zero if c is a letter or digit, else 0', example: 'if (isalnum((unsigned char)s[i]))\n    word_len++;' },
  { name: 'isspace', kind: 'function', sig: 'int isspace(int c)', params: [{ label: 'c', doc: 'character' }], doc: 'Non-zero for space, `\\t`, `\\n`, `\\v`, `\\f`, `\\r`.', header: '#include <ctype.h>', returns: 'int — non-zero for \' \', \'\\t\', \'\\n\', \'\\v\', \'\\f\', \'\\r\', else 0', example: 'while (isspace((unsigned char)*p))\n    p++;' },
  { name: 'isupper', kind: 'function', sig: 'int isupper(int c)', params: [{ label: 'c', doc: 'character' }], doc: 'Non-zero if *c* is an uppercase letter.', header: '#include <ctype.h>', returns: 'int — non-zero if c is an uppercase letter, else 0', example: 'if (isupper((unsigned char)c))\n    caps++;' },
  { name: 'islower', kind: 'function', sig: 'int islower(int c)', params: [{ label: 'c', doc: 'character' }], doc: 'Non-zero if *c* is a lowercase letter.', header: '#include <ctype.h>', returns: 'int — non-zero if c is a lowercase letter, else 0', example: 'if (islower((unsigned char)c))\n    c = toupper(c);' },
  { name: 'ispunct', kind: 'function', sig: 'int ispunct(int c)', params: [{ label: 'c', doc: 'character' }], doc: 'Non-zero for printable non-alphanumeric, non-space characters.', header: '#include <ctype.h>', returns: 'int — non-zero if c is printable punctuation, else 0', example: 'if (ispunct((unsigned char)c))\n    punct++;' },
  { name: 'toupper', kind: 'function', sig: 'int toupper(int c)', params: [{ label: 'c', doc: 'character' }], doc: 'Uppercase version of *c* (unchanged if not a lowercase letter). Returns `int` — cast/assign to char.', header: '#include <ctype.h>', returns: 'int — the uppercase equivalent, or c unchanged if not a lowercase letter', example: 'for (char *p = s; *p; p++)\n    *p = toupper((unsigned char)*p);' },
  { name: 'tolower', kind: 'function', sig: 'int tolower(int c)', params: [{ label: 'c', doc: 'character' }], doc: 'Lowercase version of *c* (unchanged if not an uppercase letter).', example: 'for (int i = 0; s[i]; i++) s[i] = tolower((unsigned char)s[i]);', header: '#include <ctype.h>', returns: 'int — the lowercase equivalent, or c unchanged if not an uppercase letter' },

  // ───────────── math.h ─────────────
  { name: 'sqrt', kind: 'function', sig: 'double sqrt(double x)', params: [{ label: 'x', doc: 'non-negative value' }], doc: 'Square root. For integer sqrt, correct the result: `while (r * r > n) r--;` since floating error can be off by one for large n.', header: '#include <math.h>', returns: 'double — the non-negative square root (NaN for x < 0)', example: 'double d = sqrt(dx * dx + dy * dy);' },
  { name: 'pow', kind: 'function', sig: 'double pow(double base, double exp)', params: [{ label: 'base', doc: 'base' }, { label: 'exp', doc: 'exponent' }], doc: 'Floating-point power. Don\'t use for integer powers/mod arithmetic — precision loss; write fast exponentiation instead.', header: '#include <math.h>', returns: 'double — base raised to exp', example: 'double vol = pow(side, 3);  // side cubed' },
  { name: 'fabs', kind: 'function', sig: 'double fabs(double x)', params: [{ label: 'x', doc: 'value' }], doc: 'Absolute value of a double (`abs` truncates to int!).', header: '#include <math.h>', returns: 'double — |x|', example: 'if (fabs(a - b) < 1e-9)\n    puts("equal");' },
  { name: 'floor', kind: 'function', sig: 'double floor(double x)', params: [{ label: 'x', doc: 'value' }], doc: 'Largest integer ≤ x, as a double. For positive ints, `a / b` already floors; ceil-div is `(a + b - 1) / b`.', header: '#include <math.h>', returns: 'double — largest integer value <= x', example: 'int bucket = (int)floor(x / width);' },
  { name: 'ceil', kind: 'function', sig: 'double ceil(double x)', params: [{ label: 'x', doc: 'value' }], doc: 'Smallest integer ≥ x, as a double. Prefer integer `(a + b - 1) / b` for positive ints.', header: '#include <math.h>', returns: 'double — smallest integer value >= x', example: 'int pages = (int)ceil((double)items / per_page);' },
  { name: 'round', kind: 'function', sig: 'double round(double x)', params: [{ label: 'x', doc: 'value' }], doc: 'Round to nearest, halves away from zero. `llround` returns a long long.', header: '#include <math.h>', returns: 'double — x rounded to nearest integer, halves away from zero', example: 'long cents = (long)round(price * 100);' },
  { name: 'trunc', kind: 'function', sig: 'double trunc(double x)', params: [{ label: 'x', doc: 'value' }], doc: 'Round toward zero.', header: '#include <math.h>', returns: 'double — x with the fractional part removed (toward zero)', example: 'double whole = trunc(-2.7);  // -2.0' },
  { name: 'fmin', kind: 'function', sig: 'double fmin(double x, double y)', params: [{ label: 'x', doc: 'first value' }, { label: 'y', doc: 'second value' }], doc: 'Smaller of two doubles. C has no generic integer `min` — write `a < b ? a : b` or a macro.', header: '#include <math.h>', returns: 'double — the smaller of x and y', example: 'best = fmin(best, cost);' },
  { name: 'fmax', kind: 'function', sig: 'double fmax(double x, double y)', params: [{ label: 'x', doc: 'first value' }, { label: 'y', doc: 'second value' }], doc: 'Larger of two doubles. Converting large long longs to double loses precision — use a ternary for integers.', header: '#include <math.h>', returns: 'double — the larger of x and y', example: 'peak = fmax(peak, value);' },
  { name: 'fmod', kind: 'function', sig: 'double fmod(double x, double y)', params: [{ label: 'x', doc: 'dividend' }, { label: 'y', doc: 'divisor' }], doc: 'Floating-point remainder (sign follows x).', header: '#include <math.h>', returns: 'double — remainder of x / y with the sign of x', example: 'double angle = fmod(theta, 360.0);' },
  { name: 'log', kind: 'function', sig: 'double log(double x)', params: [{ label: 'x', doc: 'positive value' }], doc: 'Natural logarithm.', header: '#include <math.h>', returns: 'double — natural logarithm (base e) of x', example: 'double bits = log(n) / log(2);' },
  { name: 'log2', kind: 'function', sig: 'double log2(double x)', params: [{ label: 'x', doc: 'positive value' }], doc: 'Base-2 logarithm. For integer bit length prefer `31 - __builtin_clz(x)`.', header: '#include <math.h>', returns: 'double — base-2 logarithm of x', example: 'int depth = (int)ceil(log2(n));' },
  { name: 'log10', kind: 'function', sig: 'double log10(double x)', params: [{ label: 'x', doc: 'positive value' }], doc: 'Base-10 logarithm.', header: '#include <math.h>', returns: 'double — base-10 logarithm of x', example: 'int digits = (int)log10(n) + 1;  // n > 0' },
  { name: 'exp', kind: 'function', sig: 'double exp(double x)', params: [{ label: 'x', doc: 'exponent' }], doc: 'e raised to *x*.', header: '#include <math.h>', returns: 'double — e raised to x', example: 'double growth = exp(rate * t);' },
  { name: 'hypot', kind: 'function', sig: 'double hypot(double x, double y)', params: [{ label: 'x', doc: 'leg' }, { label: 'y', doc: 'leg' }], doc: 'sqrt(x²+y²) without intermediate overflow. For comparing distances, compare squared integer distances instead.', header: '#include <math.h>', returns: 'double — sqrt(x*x + y*y) without intermediate overflow', example: 'double dist = hypot(x2 - x1, y2 - y1);' },
  { name: 'INFINITY', kind: 'constant', sig: '#define INFINITY ...', doc: 'Positive floating infinity (float). For integer "infinity" use `INT_MAX` / `LLONG_MAX` (careful adding to them) or a sentinel like `1e9`.', header: '#include <math.h>', example: 'double best = INFINITY;\nif (cost < best) best = cost;' },
  { name: 'NAN', kind: 'constant', sig: '#define NAN ...', doc: 'Quiet NaN. `x != x` is true only for NaN; use `isnan(x)`.', header: '#include <math.h>', example: 'double r = NAN;\nif (isnan(r)) puts("no result");' },

  // ───────────── limits.h / stdint.h ─────────────
  { name: 'INT_MAX', kind: 'constant', sig: '#define INT_MAX 2147483647', doc: 'Max `int` (2³¹−1). `INT_MAX + 1` overflows (UB). Common "infinity" for min-tracking.', header: '#include <limits.h>', example: 'int best = INT_MAX;\nfor (int i = 0; i < n; i++) if (a[i] < best) best = a[i];' },
  { name: 'INT_MIN', kind: 'constant', sig: '#define INT_MIN (-2147483647 - 1)', doc: 'Min `int` (−2³¹). `-INT_MIN` and `abs(INT_MIN)` overflow.', header: '#include <limits.h>', example: 'int best = INT_MIN;\nfor (int i = 0; i < n; i++) if (a[i] > best) best = a[i];' },
  { name: 'UINT_MAX', kind: 'constant', sig: '#define UINT_MAX 4294967295U', doc: 'Max `unsigned int` (2³²−1).', header: '#include <limits.h>', example: 'unsigned int all = UINT_MAX;  // every bit set' },
  { name: 'LLONG_MAX', kind: 'constant', sig: '#define LLONG_MAX 9223372036854775807LL', doc: 'Max `long long` (2⁶³−1 ≈ 9.2e18).', header: '#include <limits.h>', example: 'long long dist = LLONG_MAX;  // "infinity" for shortest paths' },
  { name: 'LLONG_MIN', kind: 'constant', sig: '#define LLONG_MIN (-LLONG_MAX - 1)', doc: 'Min `long long` (−2⁶³).', header: '#include <limits.h>', example: 'long long best = LLONG_MIN;' },
  { name: 'LONG_MAX', kind: 'constant', sig: '#define LONG_MAX ...', doc: 'Max `long` — platform dependent (2⁶³−1 on Linux/macOS, 2³¹−1 on Windows).', header: '#include <limits.h>', example: 'if (v == LONG_MAX && errno == ERANGE) puts("overflow");' },
  { name: 'LONG_MIN', kind: 'constant', sig: '#define LONG_MIN ...', doc: 'Min `long` — platform dependent.', header: '#include <limits.h>', example: 'long lo = LONG_MIN;' },
  { name: 'CHAR_BIT', kind: 'constant', sig: '#define CHAR_BIT 8', doc: 'Bits per byte (8).', header: '#include <limits.h>', example: 'int bits = sizeof(int) * CHAR_BIT;  // 32 on typical platforms' },
  { name: 'int8_t', kind: 'type', sig: 'int8_t', doc: 'Exactly 8-bit signed integer.', header: '#include <stdint.h>', example: 'int8_t delta = -3;' },
  { name: 'int16_t', kind: 'type', sig: 'int16_t', doc: 'Exactly 16-bit signed integer.', header: '#include <stdint.h>', example: 'int16_t sample = -1200;' },
  { name: 'int32_t', kind: 'type', sig: 'int32_t', doc: 'Exactly 32-bit signed integer.', header: '#include <stdint.h>', example: 'int32_t x = 123456;' },
  { name: 'int64_t', kind: 'type', sig: 'int64_t', doc: 'Exactly 64-bit signed integer. Print portably with `"%" PRId64` (`<inttypes.h>`), or cast to `long long` and use `%lld`.', header: '#include <stdint.h>', example: 'int64_t total = 0;\nprintf("%lld\\n", (long long)total);' },
  { name: 'uint8_t', kind: 'type', sig: 'uint8_t', doc: 'Exactly 8-bit unsigned integer (0..255).', header: '#include <stdint.h>', example: 'uint8_t pixel = 255;' },
  { name: 'uint16_t', kind: 'type', sig: 'uint16_t', doc: 'Exactly 16-bit unsigned integer.', header: '#include <stdint.h>', example: 'uint16_t port = 8080;' },
  { name: 'uint32_t', kind: 'type', sig: 'uint32_t', doc: 'Exactly 32-bit unsigned integer — used by bit problems like "reverse bits" / "number of 1 bits". Wraps mod 2³².', header: '#include <stdint.h>', example: 'uint32_t hash = 2166136261u;' },
  { name: 'uint64_t', kind: 'type', sig: 'uint64_t', doc: 'Exactly 64-bit unsigned integer; good for hashing (wrap-around is defined).', header: '#include <stdint.h>', example: 'uint64_t mask = 1ULL << 40;' },
  { name: 'INT32_MAX', kind: 'constant', sig: '#define INT32_MAX 2147483647', doc: 'Max `int32_t`.', header: '#include <stdint.h>', example: 'int32_t best = INT32_MAX;' },
  { name: 'INT64_MAX', kind: 'constant', sig: '#define INT64_MAX 9223372036854775807', doc: 'Max `int64_t`.', header: '#include <stdint.h>', example: 'int64_t best = INT64_MAX;' },
  { name: 'UINT32_MAX', kind: 'constant', sig: '#define UINT32_MAX 4294967295U', doc: 'Max `uint32_t`.', header: '#include <stdint.h>', example: 'uint32_t all = UINT32_MAX;' },

  // ───────────── stdbool.h ─────────────
  { name: 'bool', kind: 'type', sig: 'bool', doc: 'Boolean type (alias for `_Bool`); needs `<stdbool.h>` before C23. LeetCode C signatures use it for yes/no answers.', header: '#include <stdbool.h>', example: 'bool found = false;\nif (found) puts("yes");' },
  { name: 'true', kind: 'constant', sig: '#define true 1', doc: 'Boolean true (1).', header: '#include <stdbool.h>', example: 'bool running = true;\nwhile (running) { /* ... */ }' },
  { name: 'false', kind: 'constant', sig: '#define false 0', doc: 'Boolean false (0).', header: '#include <stdbool.h>', example: 'bool seen[256] = { false };' },

  // ───────────── errno.h / time.h ─────────────
  { name: 'errno', kind: 'macro', sig: 'int errno', returns: 'int — the error code set by the last failing library call', doc: 'Thread-local error code set by many library functions **on failure** (successful calls may leave it unchanged). Set `errno = 0` before a call like `strtol` if you need to detect errors; compare with constants like `ERANGE`, `ENOENT`.', example: 'errno = 0;\nlong v = strtol(s, NULL, 10);\nif (errno == ERANGE) puts("out of range");', header: '#include <errno.h>' },
  { name: 'strerror', kind: 'function', sig: 'char *strerror(int errnum)', params: [{ label: 'errnum', doc: 'an error code, usually errno' }], returns: 'char * — a human-readable message for errnum (do not modify or free)', doc: 'Translate an error code into text, e.g. "No such file or directory".', example: 'if (!f)\n    fprintf(stderr, "open %s: %s\\n", path, strerror(errno));', header: '#include <string.h>' },
  { name: 'time', kind: 'function', sig: 'time_t time(time_t *tloc)', params: [{ label: 'tloc', doc: 'if non-NULL, the result is also stored here; usually pass NULL' }], returns: 'time_t — current calendar time in seconds since the Unix epoch, or (time_t)-1 on error', doc: 'Get the current wall-clock time in seconds. Most commonly used to seed `srand`.', example: 'srand((unsigned)time(NULL));', header: '#include <time.h>' },
  { name: 'clock', kind: 'function', sig: 'clock_t clock(void)', returns: 'clock_t — processor time used so far in CLOCKS_PER_SEC units, or (clock_t)-1 if unavailable', doc: 'Measure CPU time consumed by the program. Divide a difference by `CLOCKS_PER_SEC` to get seconds.', example: 'clock_t t0 = clock();\nsolve();\nprintf("%.3f s\\n", (double)(clock() - t0) / CLOCKS_PER_SEC);', header: '#include <time.h>' },
  { name: 'CLOCKS_PER_SEC', kind: 'constant', sig: '#define CLOCKS_PER_SEC ...', doc: 'Number of `clock()` ticks per second (1000000 on POSIX systems).', example: 'double secs = (double)(end - start) / CLOCKS_PER_SEC;', header: '#include <time.h>' },

  // ───────────── assert.h ─────────────
  { name: 'assert', kind: 'macro', sig: 'void assert(scalar expression)', params: [{ label: 'expression', doc: 'condition expected to be true' }], doc: 'Abort with a message if *expression* is false. Disabled when `NDEBUG` is defined — don\'t put side effects inside.', header: '#include <assert.h>', returns: 'void (aborts the program if expression is false)', example: 'assert(n > 0);\nassert(ptr != NULL);' },

  // ───────────── builtins (GCC/Clang) ─────────────
  { name: '__builtin_popcount', kind: 'function', sig: 'int __builtin_popcount(unsigned int x)', params: [{ label: 'x', doc: 'value' }], doc: 'Number of set bits (GCC/Clang builtin). Use `__builtin_popcountll` for 64-bit.', returns: 'int — number of 1 bits in x', example: 'int bits = __builtin_popcount(mask);' },
  { name: '__builtin_popcountll', kind: 'function', sig: 'int __builtin_popcountll(unsigned long long x)', params: [{ label: 'x', doc: 'value' }], doc: 'Number of set bits in a 64-bit value.', returns: 'int — number of 1 bits in x', example: 'int bits = __builtin_popcountll(mask64);' },
  { name: '__builtin_clz', kind: 'function', sig: 'int __builtin_clz(unsigned int x)', params: [{ label: 'x', doc: 'non-zero value' }], doc: 'Count leading zero bits. **Undefined for x == 0.** `31 - __builtin_clz(x)` = floor(log2 x).', returns: 'int — number of leading zero bits (undefined for x == 0)', example: 'int highest = 31 - __builtin_clz(x);  // index of top set bit, x > 0' },
  { name: '__builtin_ctz', kind: 'function', sig: 'int __builtin_ctz(unsigned int x)', params: [{ label: 'x', doc: 'non-zero value' }], doc: 'Count trailing zero bits (index of lowest set bit). **Undefined for x == 0.**', returns: 'int — number of trailing zero bits (undefined for x == 0)', example: 'int lowest = __builtin_ctz(x);  // index of lowest set bit, x > 0' },

  // ───────────── snippets / idioms ─────────────
  { name: 'returnSize', kind: 'snippet', sig: 'int *returnSize', doc: 'LeetCode out-parameter: set `*returnSize` to the length of the malloc-ed array you return. For 2-D results also fill `*returnColumnSizes` with a malloc-ed array of row lengths.', example: 'int *res = malloc(k * sizeof(int));\n*returnSize = k;\nreturn res;', insert: '*returnSize = ${1:n};' },
  { name: 'returnColumnSizes', kind: 'snippet', sig: 'int **returnColumnSizes', doc: 'LeetCode out-parameter for 2-D results: `*returnColumnSizes = malloc(rows * sizeof(int));` then set each `(*returnColumnSizes)[i]`.', example: 'int **res = malloc(rows * sizeof(int *));\n*returnColumnSizes = malloc(rows * sizeof(int));\nfor (int i = 0; i < rows; i++) { res[i] = malloc(cols * sizeof(int)); (*returnColumnSizes)[i] = cols; }\n*returnSize = rows;' },
  { name: 'cmp', kind: 'snippet', sig: 'int cmp(const void *a, const void *b)', params: [{ label: 'a', doc: 'pointer to first element' }, { label: 'b', doc: 'pointer to second element' }], doc: 'Overflow-safe ascending int comparator for `qsort` / `bsearch`. Swap a and b for descending.', insert: 'int ${1:cmp}(const void *a, const void *b) {\n\tint x = *(const int *)a, y = *(const int *)b;\n\treturn (x > y) - (x < y);\n}', example: 'int cmp(const void *a, const void *b) {\n    int x = *(const int *)a, y = *(const int *)b;\n    return (x > y) - (x < y);\n}' },
  { name: 'MAX', kind: 'snippet', sig: '#define MAX(a, b) ((a) > (b) ? (a) : (b))', doc: 'C has no generic max; this macro is the usual stand-in. Arguments may be evaluated twice.', insert: '#define MAX(a, b) ((a) > (b) ? (a) : (b))', example: '#define MAX(a, b) ((a) > (b) ? (a) : (b))\nbest = MAX(best, cur);' },
  { name: 'MIN', kind: 'snippet', sig: '#define MIN(a, b) ((a) < (b) ? (a) : (b))', doc: 'Generic min macro. Arguments may be evaluated twice — avoid `MIN(i++, j)`.', insert: '#define MIN(a, b) ((a) < (b) ? (a) : (b))', example: '#define MIN(a, b) ((a) < (b) ? (a) : (b))\nlo = MIN(lo, a[i]);' },
  { name: 'ListNode', kind: 'type', sig: 'struct ListNode { int val; struct ListNode *next; };', doc: 'LeetCode singly-linked list node (predefined). Allocate with `malloc(sizeof(struct ListNode))`; a dummy head node simplifies edge cases.', example: 'struct ListNode dummy = { 0, head }, *cur = &dummy;' },
  { name: 'TreeNode', kind: 'type', sig: 'struct TreeNode { int val; struct TreeNode *left; struct TreeNode *right; };', doc: 'LeetCode binary tree node (predefined). Recursion depth can reach n on skewed trees.', example: 'int depth(struct TreeNode *t) {\n    if (!t) return 0;\n    int l = depth(t->left), r = depth(t->right);\n    return 1 + (l > r ? l : r);\n}' },
];
